clear;clc;n = 0:127;x = sin(2*pi*n/16) + 0.3*randn(size(n));X = fft(x, 128);window_rect = ones(1,128);window_hamming = hamming(128)';window_blackman = blackman(128)';X_rect = fft(x.*window_rect, 128);X_hamming = fft(x.*window_hamming, 128);X_blackman = fft(x.*window_blackman, 128);figure;subplot(2,2,1);plot(0:127, abs(X_rect));title('$\mathrm{Rectangular\ Window}$', 'Interpreter', 'latex');subplot(2,2,2);plot(0:127, abs(X_hamming));title('$\mathrm{Hamming\ Window}$', 'Interpreter', 'latex');subplot(2,2,3);plot(0:127, abs(X_blackman));title('$\mathrm{Blackman\ Window}$', 'Interpreter', 'latex');subplot(2,2,4);plot(0:127, abs(X));title('$\mathrm{No\ Window}$', 'Interpreter', 'latex');